[{"order":1,"type":"heading","text":"Enterprise Observability in .NET with OpenTelemetry and Serilog"},{"order":2,"type":"paragraph","text":"Modern cloud-native applications require robust observability to diagnose performance bottlenecks and unexpected behaviors in production. Observability relies on three core pillars: Metrics, Distributed Tracing, and Structured Logging. In the .NET ecosystem, OpenTelemetry has become the industry standard for collecting telemetry data, while Serilog provides high-performance structured logging."},{"order":3,"type":"subheading","text":"1. Installing Required Packages"},{"order":4,"type":"paragraph","text":"To enable OpenTelemetry and Serilog in your ASP.NET Core application, you need to install the necessary NuGet packages. Run the following commands in your terminal:"},{"order":5,"type":"code","text":"dotnet add package Serilog.AspNetCore
dotnet add package Serilog.Sinks.Console
dotnet add package OpenTelemetry.Extensions.Hosting
dotnet add package OpenTelemetry.Instrumentation.AspNetCore
dotnet add package OpenTelemetry.Instrumentation.Http
dotnet add package OpenTelemetry.Exporter.OpenTelemetryProtocol"},{"order":6,"type":"subheading","text":"2. Configuring Serilog for Structured Logging"},{"order":7,"type":"paragraph","text":"Structured logging allows you to capture rich context alongside your log messages rather than raw strings. Configure Serilog in your Program.cs file to enrich logs with machine names, thread IDs, and contextual data."},{"order":8,"type":"code","text":"Log.Logger = new LoggerConfiguration()
    .Enrich.FromLogContext()
    .Enrich.WithMachineName()
    .WriteTo.Console()
    .CreateBootstrapLogger();

try
{
    Log.Information("Starting web application");
    var builder = WebApplication.CreateBuilder(args);
    builder.Host.UseSerilog((context, services, configuration) => configuration
        .ReadFrom.Configuration(context.Configuration)
        .ReadFrom.Services(services)
        .Enrich.FromLogContext()
        .WriteTo.Console());
"},{"order":9,"type":"subheading","text":"3. Integrating OpenTelemetry for Metrics and Tracing"},{"order":10,"type":"paragraph","text":"OpenTelemetry unifies the collection of metrics and traces. We configure the OpenTelemetry service provider in .NET to listen to ASP.NET Core and HttpClient events, and export them using the OTLP protocol."},{"order":11,"type":"code","text":"    builder.Services.AddOpenTelemetry()
        .WithTracing(tracing => tracing
            .AddSource("MyCompany.MyService")
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("OrderService"))
            .AddAspNetCoreInstrumentation()
            .AddHttpClientInstrumentation()
            .AddOtlpExporter(opts => opts.Endpoint = new Uri("http://localhost:4317")))
        .WithMetrics(metrics => metrics
            .AddAspNetCoreInstrumentation()
            .AddHttpClientInstrumentation()
            .AddMeter("Microsoft.AspNetCore.Hosting")
            .AddMeter("Microsoft.AspNetCore.Server.Kestrel")
            .AddOtlpExporter(opts => opts.Endpoint = new Uri("http://localhost:4317")));
"},{"order":12,"type":"subheading","text":"4. Writing Observable Code in Controllers"},{"order":13,"type":"paragraph","text":"When writing business logic, use structured templates in your logs and ensure you correlate logs with the active trace context provided by OpenTelemetry."},{"order":14,"type":"code","text":"[ApiController]
[Route("[controller]")]
public class OrdersController : ControllerBase
{
    private readonly ILogger<OrdersController> _logger;
    private readonly ActivitySource _activitySource = new ActivitySource("MyCompany.MyService");

    public OrdersController(ILogger<OrdersController> logger)
    {
        _logger = logger;
    }

    [HttpGet("{id}")]
    public IActionResult GetOrder(int id)
    {
        using var activity = _activitySource.StartActivity("ProcessGetOrder");
        activity?.SetTag("order.id", id);

        _logger.LogInformation("Fetching order with ID {OrderId} at {Timestamp}", id, DateTime.UtcNow);

        if (id <= 0)
        {
            _logger.LogWarning("Invalid order ID requested: {OrderId}", id);
            return BadRequest("Invalid Order ID");
        }

        return Ok(new { OrderId = id, Status = "Processed" });
    }
}"},{"order":15,"type":"subheading","text":"5. Best Practices for Production"},{"order":16,"type":"bullet_point","text":"Always use template parameters in Serilog (e.g., _logger.LogInformation("User {UserId} logged in", userId)) instead of string interpolation to enable proper indexing in log aggregators."},{"order":17,"type":"bullet_point","text":"Configure sampling rates in high-throughput production environments to manage OpenTelemetry data volumes and cost."},{"order":18,"type":"bullet_point","text":"Ensure correlation IDs are passed across microservice boundaries using standard W3C Trace Context headers."}]
